/**
 * Execute Proposal
 *
 * Moves a PASSED proposal to EXECUTED — the formal "this decision has
 * been enacted" marker. Not idempotent like finalize: a proposal can only
 * be executed once, so a second call 400s rather than silently returning
 * the same result, matching disputes.py's enforce_ruling precedent for
 * the same "who did this and when" shape (executed_by/executed_at here,
 * enforced_by/resolved_at there).
 *
 * No real on-chain effect is wired up yet (no treasury transfer, no
 * parameter change) — see ROADMAP.md Part 3; this is deliberately scoped
 * to just the status transition until there's a real effect to apply.
 */
export const executeProposalProposalsProposalIdExecutePost = <ThrowOnError extends boolean = false>(options: Options<ExecuteProposalProposalsProposalIdExecutePostData, ThrowOnError>): RequestResult<ExecuteProposalProposalsProposalIdExecutePostResponses, ExecuteProposalProposalsProposalIdExecutePostErrors, ThrowOnError> => (options.client ?? client).post<ExecuteProposalProposalsProposalIdExecutePostResponses, ExecuteProposalProposalsProposalIdExecutePostErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/proposals/{proposal_id}/execute',
    ...options
});

/**
 * Finalize Proposal
 *
 * Idempotent — an already-finalized proposal is returned as-is rather
 * than re-evaluated, so calling this twice is always safe. Raises 400 if
 * `end_time` hasn't arrived yet; a future bulk sweep (ROADMAP.md Part 1's
 * cron) should filter to `end_time <= now()` itself before calling this
 * per-id rather than relying on the 400 to skip early proposals.
 */
export const finalizeProposalProposalsProposalIdFinalizePost = <ThrowOnError extends boolean = false>(options: Options<FinalizeProposalProposalsProposalIdFinalizePostData, ThrowOnError>): RequestResult<FinalizeProposalProposalsProposalIdFinalizePostResponses, FinalizeProposalProposalsProposalIdFinalizePostErrors, ThrowOnError> => (options.client ?? client).post<FinalizeProposalProposalsProposalIdFinalizePostResponses, FinalizeProposalProposalsProposalIdFinalizePostErrors, ThrowOnError>({ url: '/proposals/{proposal_id}/finalize', ...options });

